    <dialog ref="detailDialog" class="qv-dialog qv-detail" aria-labelledby="qv-detail-title" @cancel.prevent="closeDetail" @close="stopPlayer"><header><div><span class="qv-eyebrow">QGAUSS / PRIVATE SCREENING</span><h2 id="qv-detail-title">这一幕，值得停留。</h2></div><button type="button" class="qv-icon-button" aria-label="关闭视频详情" @click="closeDetail">×</button></header><BrandLoader v-if="detailLoading" text="正在准备放映…" /><template v-else-if="detail"><div class="qv-player"><video v-if="detail.status === 'SUCCESS' && detailMedia?.videoUrl" ref="player" :src="detailMedia.videoUrl" :poster="detailMedia.posterUrl || undefined" controls playsinline preload="metadata" aria-label="成片播放器" @error="playError = '成片暂未播放，链接可能已过期，请刷新播放地址。'" @loadedmetadata="resumePlayer"></video><div v-else class="qv-player-status"><BrandLoader v-if="videoActive(detail.status)" /><b>{{ videoStatus(detail.status) }}</b><p>{{ detail.message }}</p></div></div><div v-if="playError" class="qv-alert" role="alert">{{ playError }}<button type="button" @click="refreshPlayback">刷新播放地址</button></div><div class="qv-detail-info"><div><span class="qv-status">{{ videoStatus(detail.status) }}</span><h3>画面里的想法</h3><p>{{ detail.prompt }}</p><div class="qv-specs"><span>{{ detail.presetName }}</span><span>{{ detail.ratio==='source'?'保留原片画幅':detail.ratio==='adaptive'?'自适应画幅':detail.ratio }}</span><span v-if="detail.seconds">{{ detail.seconds }} 秒</span><span>{{ detail.resolution }}</span><span v-if="detail.seed !== null && detail.seed !== undefined">种子 {{ detail.seed }}</span></div></div><dl v-if="detail.mine && detail.billing" class="qv-bill"><div><dt>已预留</dt><dd>{{ detail.billing.reserved }} 次</dd></div><div><dt>本次结算</dt><dd>{{ detail.billing.charged }} 次</dd></div><div><dt>已释放</dt><dd>{{ detail.billing.returned }} 次</dd></div><div v-if="detail.billing.expired"><dt>已过期权益</dt><dd>{{ detail.billing.expired }} 次</dd></div></dl></div><div class="qv-detail-buttons"><button v-for="tool in [{key:'upscale',label:'放大更清晰'},{key:'lipsync',label:'给这一幕配音'},{key:'edit',label:'改写这一幕'}].filter(x=>detail.mine && detail.status === 'SUCCESS' && presets.some(p=>p.ready && p.features.modes.includes(x.key)))" :key="tool.key" type="button" :disabled="materialBusy" @click="beginTool(detail,tool.key)">{{ tool.label }} ↗</button><button v-if="detail.status === 'SUCCESS'" type="button" class="qv-primary" :disabled="downloading" @click="downloadMovie">{{ downloading ? '准备下载…' : '下载成片' }} ↓</button><button type="button" @click="reuse(detail)">带着灵感再创作</button><button v-if="detail.mine && detail.canExtend && detail.status === 'SUCCESS'" type="button" @click="extend(detail)">续写下一幕 ↗</button><button v-if="detail.mine && detail.status === 'SUCCESS'" type="button" :disabled="busy.has(detail.id)" @click="publishConfirm = true">{{ detail.published ? '撤回公开' : '发布到放映厅' }}</button><button v-if="detail.mine && !videoActive(detail.status)" type="button" :disabled="busy.has(detail.id)" @click="deleteConfirm = true">移入回收</button><button v-if="detail.mine && ['QUEUED','SUBMITTING','POLLING'].includes(detail.status)" type="button" :disabled="busy.has(detail.id)" @click="stopTask(detail)">停止等待</button></div><div v-if="publishConfirm" class="qv-inline-confirm"><p>{{ detail.published ? '撤回后，其他用户将不能再打开新的播放请求。已下载的成片无法远程收回。' : '公开后，站内用户可观看与下载成片，查看提示词和画幅参数。私有参考图及费用不会公开。' }}</p><button type="button" :disabled="busy.has(detail.id)" @click="togglePublish">确认{{ detail.published ? '撤回' : '公开' }}</button><button type="button" @click="publishConfirm = false">保留现状</button></div><div v-if="deleteConfirm" class="qv-inline-confirm"><p>移入回收后将从片库和放映厅隐藏，已有费用不改变。</p><button type="button" :disabled="busy.has(detail.id)" @click="removeTask">确认移入回收</button><button type="button" @click="deleteConfirm = false">保留成片</button></div><p v-if="detail.mine && ['SUBMITTING','POLLING'].includes(detail.status)" class="qv-muted">停止等待会释放站内预留；服务方仍可能继续计算或产生外部费用。</p><details v-if="detail.events?.length" class="qv-events"><summary>创作足迹</summary><ol><li v-for="e in detail.events" :key="e.id"><b>{{ e.message }}</b><time>{{ date(e.createdAt) }}</time></li></ol></details></template><div v-else-if="detailError" class="qv-alert" role="alert">{{ detailError }}</div></dialog></Teleport>
