function scope(key) { controllers.get(key)?.abort(); const controller = new AbortController(); controllers.set(key, controller); return { signal: controller.signal, current: () => current() && !controller.signal.aborted && controllers.get(key) === controller }; }
const form = reactive({ presetId: '', mode: 'text', prompt: '', ratio: '16:9', resolution: '720p', seconds: 5, seed: '', style: '', motion: 1, guidanceScale: 16, frameRate: 24, pan: '', tilt: '', rotate: '', zoom: '', negativePrompt: '', sound: true, upscaleFactor: 2, enhanceModel: 'Proteus', syncMode: 'cut_off', compression: 0, noise: 0, halo: 0, grain: 0, recoverDetail: 0, customEnhance: false });
const presets = ref([]), optionsLoaded = ref(false), optionsError = ref(''), references = ref([]), sourceTask = ref(null), fileInput = ref(null), uploading = ref(false);
