const materialMovies = computed(() => tab.value === 'mine' ? tasks.value.filter(t => t.mine && t.status === 'SUCCESS') : []);
const timeChoices = computed(() => ['edit','upscale','lipsync'].includes(form.mode) ? [0] : selected.value?.features.seconds || [0]);
const legacyExtend = computed(() => selected.value?.profile === 'PIKA_1' && form.mode === 'extend' && !!sourceTask.value);
const selected = computed(() => presets.value.find(p => p.id === form.presetId)), activeCount = computed(() => tasks.value.filter(t => videoActive(t.status)).length);
const allowedRatios = computed(() => ['upscale','lipsync'].includes(form.mode) ? ['source'] : form.mode === 'edit' ? ['adaptive'] : selected.value?.features.adaptiveImage && ['image', 'extend'].includes(form.mode) ? ['adaptive'] : selected.value?.features.ratios || ['16:9', '9:16', '1:1']);
const estimate = computed(() => { const p = selected.value?.pricing; if (!p || videoToolMode(form.mode)) return '素材、时长与处理选项会一起核对，确认后才预留次数'; return '预计 ' + (p.base + p.perSecond * (form.seconds || 0)) + ' ' + (videoPools[p.pool] || '次数') + ' · 开机前再次确认'; });
const tasks = ref([]), total = ref(0), page = ref(1), pageSize = 12, tab = ref('mine'), loading = ref(false), listError = ref(''), media = reactive(new Map()), busy = reactive(new Set());
const quoting = ref(false), submitting = ref(false), recovering = ref(false), pendingIntent = ref(intentStore.read()), quote = ref(null), quotePayload = ref(null), confirmDialog = ref(null);
const detail = ref(null), detailDialog = ref(null), detailLoading = ref(false), detailError = ref(''), detailMedia = ref(null), player = ref(null), playError = ref(''), downloading = ref(false), publishConfirm = ref(false), deleteConfirm = ref(false);
const modeChoices = videoModes;
const toolHero={reference:{first:'把灵感，',second:'混成下一幕。'},edit:{first:'同一条片，',second:'不同的可能。'},upscale:{first:'把细节，',second:'重新点亮。'},lipsync:{first:'让声音，',second:'长出表情。'}};
const cameraChoices = [{ key: 'pan', label: '横向运镜', values: [{ key: 'left', label: '向左' }, { key: 'right', label: '向右' }] }, { key: 'tilt', label: '俯仰运镜', values: [{ key: 'up', label: '向上' }, { key: 'down', label: '向下' }] }, { key: 'rotate', label: '旋转镜头', values: [{ key: 'cw', label: '顺时针' }, { key: 'ccw', label: '逆时针' }] }, { key: 'zoom', label: '镜头远近', values: [{ key: 'in', label: '推近' }, { key: 'out', label: '拉远' }] }];
const ideas = [{ title: '漂浮的微光', tag: '柔光 · 缓慢推镜', icon: '✦', prompt: '一个透明玻璃小球漂浮在柔软云层间，薰衣草与冰蓝渐变，清晨柔光，镜头缓慢推进，轻盈梦幻，细腻的 3D 材质。' }, { title: '青柠色的风', tag: '轻快 · 材质特写', icon: '◒', prompt: '一颗青柠色软胶 Q 形雕塑轻轻旋转，奶油色背景，风吹动一小片透明薄膜，镜头环绕，活泼清新的产品短片。' }, { title: '宇宙来信', tag: '极光 · 电影感', icon: '◌', prompt: '深蓝色星空中，一封半透明的信缓慢展开，青紫色极光流动，细小星尘悬浮，镜头轻轻拉远，安静而浪漫的电影氛围。' }];
const date = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '';
const referenceUrl = item => localUrls.get(item.id) || assets.urls.get('/api/upload/' + item.id + '/raw') || '';
async function loadOptions() { const req = scope('options'); optionsError.value = ''; try { const data = await api.get('/video/options', { signal: req.signal }); if (!req.current()) return; presets.value = data.presets || []; optionsLoaded.value = true; if (!selected.value) form.presetId = presets.value.find(p => p.ready)?.id || presets.value[0]?.id || ''; } catch (e) { if (req.current()) optionsError.value = e.message || '片场参数暂未打开'; } }
async function loadTasks() { const req = scope('list'), kind = tab.value, index = page.value; loading.value = true; listError.value = ''; try { const data = await api.get('/video/' + (kind === 'mine' ? 'tasks' : kind === 'trash' ? 'trash' : 'square') + '?page=' + index + '&pageSize=' + pageSize, { signal: req.signal }); if (!req.current()) return; tasks.value = data.items || []; total.value = data.total || 0; for (const row of tasks.value.filter(t => kind !== 'trash' && t.status === 'SUCCESS')) void loadMedia(row.id); if (detail.value && videoActive(detail.value.status)) await refreshDetail(detail.value.id, detailRevision); } catch (e) { if (req.current()) listError.value = e.message || '片库暂未打开'; } finally { if (req.current()) loading.value = false; } }
async function loadMedia(id, force = false) { if (!force && media.has(id)) return media.get(id); const req = scope('media:' + id); try { const data = await api.get('/video/tasks/' + encodeURIComponent(id) + '/playback', { signal: req.signal }); if (!req.current()) return null; media.set(id, data); return data; } catch { return null; } }
function posterFailed(id) { const value = media.get(id); if (value) media.set(id, { ...value, posterUrl: null }); }
function clearReferences() { controllers.get('upload')?.abort(); uploading.value = false; references.value = []; for (const url of localUrls.values()) URL.revokeObjectURL(url); localUrls.clear(); assets.retain(new Set()); }
function removeReference(index) { const removed = references.value.splice(index, 1)[0]; if (removed && localUrls.has(removed.id)) { URL.revokeObjectURL(localUrls.get(removed.id)); localUrls.delete(removed.id); } assets.retain(new Set(references.value.map(i => '/api/upload/' + i.id + '/raw'))); }
async function uploadReferences(event) { const files = [...event.target.files || []]; event.target.value = ''; if (!files.length || uploading.value) return; if (references.value.length + files.length > (selected.value?.features.maxImages || 1)) return ElMessage.warning('当前创作方式的参考图数量已达上限'); if (files.some(f => !/^image\/(png|jpeg|webp|gif)$/.test(f.type) || f.size > 10 * 1024 * 1024)) return ElMessage.warning('请选择不超过 10 MB 的静态图片'); const req = scope('upload'); uploading.value = true; try { for (const file of files) { const value = await uploadFile(file, { signal: req.signal }); if (!req.current()) return; localUrls.set(value.id, URL.createObjectURL(file)); references.value.push({ id: value.id, name: file.name }); } } catch (e) { if (req.current()) ElMessage.error(e.message || '参考图上传失败'); } finally { if (req.current()) uploading.value = false; } }
function payload() { const p = selected.value; if (!p?.ready) throw Error('请先选择已就绪的视频连接'); if (!form.prompt.trim() && !['upscale','lipsync'].includes(form.mode)) throw Error('先描述你想拍的这一幕'); if(videoToolMode(form.mode)){const invalid=validateVideoMaterials(form.mode,materials.value,p.features);if(invalid)throw Error(invalid);} if (form.mode === 'image' && !references.value.length) throw Error('请先选择自己的参考图'); if (form.mode === 'image' && references.value.length > p.features.maxImages) throw Error('参考图超过当前模型支持的数量'); if (form.mode === 'extend' && !sourceTask.value) throw Error('请先从自己的成片选择续写来源'); if (form.seed !== '' && (!Number.isInteger(Number(form.seed)) || Number(form.seed) < 0 || Number(form.seed) > 4294967295)) throw Error('随机种子需要是有效的非负整数'); return { presetId: form.presetId, mode: form.mode, prompt: form.prompt.trim(), ratio: form.ratio, ...(form.seconds ? { seconds: form.seconds } : {}), ...(p.features.resolutions?.length ? { resolution: form.resolution } : {}), ...(!['upscale','lipsync'].includes(form.mode) && form.seed !== '' ? { seed: Number(form.seed) } : {}), ...(p.features.sound ? { sound: form.sound } : {}), ...(form.mode === 'image' ? { imageIds: references.value.map(i => i.id) } : {}), ...(form.mode === 'extend' ? { sourceTaskId: sourceTask.value.id } : {}), ...(videoToolMode(form.mode) ? Object.fromEntries(['image','video','audio'].map(kind=>[kind+'Ids',materials.value.filter(x=>x.kind===kind).map(x=>x.id)]).filter(([,ids])=>ids.length)) : {}), ...(form.mode === 'upscale' ? Object.fromEntries(['upscaleFactor','enhanceModel',...(form.customEnhance?['compression','noise','halo','grain','recoverDetail']:[])].map(k=>[k,form[k]])) : {}), ...(form.mode === 'lipsync' ? {syncMode:form.syncMode} : {}), ...(p.features.camera ? { style: form.style, motion: form.motion, guidanceScale: form.guidanceScale, frameRate: form.frameRate, pan: form.pan, tilt: form.tilt, rotate: form.rotate, zoom: form.zoom, negativePrompt: form.negativePrompt } : {}) }; }
async function prepareQuote() { if (quoting.value || submitting.value || uploading.value || materialBusy.value) return; if (pendingIntent.value) return ElMessage.warning('请先确认上一条提交的结果'); let data; try { data = payload(); } catch (e) { return ElMessage.warning(e.message); } const req = scope('quote'); quoting.value = true; try { const result = await api.post('/video/quote', data, { signal: req.signal }); if (!req.current()) return; quote.value = result; quotePayload.value = data; confirmDialog.value.showModal(); } catch (e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) quoting.value = false; } }
function closeConfirm() { if (submitting.value) return; confirmDialog.value?.close(); }
async function confirmCreate() { if (submitting.value || !quote.value || !quotePayload.value) return; const intent = { requestKey: pendingIntent.value?.requestKey || crypto.randomUUID(), payload: quotePayload.value, quoteRevision: quote.value.revision }; pendingIntent.value = intent; intentStore.save(intent); const req = scope('submit'); submitting.value = true; try { const task = await api.post('/video/tasks', { ...intent.payload, requestKey: intent.requestKey, quoteRevision: intent.quoteRevision }, { signal: req.signal }); if (req.current()) await accepted(task); } catch (e) { if (!req.current()) return; if (e.status === 409 || e.status === 400 || e.status === 402 || e.status === 429) { pendingIntent.value = null; intentStore.clear(); ElMessage.error(e.message); if (e.status === 409) await loadOptions(); } else { try { const task = await api.get('/video/tasks/by-request/' + intent.requestKey, { signal: req.signal }); if (req.current()) await accepted(task); } catch { if (req.current()) ElMessage.warning('提交结果尚未确认，请用片库上方入口找回，避免重复开机。'); } } } finally { if (req.current()) { submitting.value = false; confirmDialog.value?.close(); } } }
async function accepted(task) { pendingIntent.value = null; intentStore.clear(); tasks.value = [task, ...tasks.value.filter(t => t.id !== task.id)].slice(0, pageSize); page.value = 1; tab.value = 'mine'; ElMessage.success('这一幕已进入片场，可以稍后回来查看。'); await loadTasks(); }
async function recoverIntent() { if (!pendingIntent.value || recovering.value) return; const req = scope('recover'); recovering.value = true; try { const task = await api.get('/video/tasks/by-request/' + pendingIntent.value.requestKey, { signal: req.signal }); if (req.current()) await accepted(task); } catch (e) { if (req.current()) ElMessage.warning(e.status === 404 ? '暂未找到这次提交，可再次确认原提交；同一意图不会重复创建。' : '暂时无法找回，请稍后再试。'); } finally { if (req.current()) recovering.value = false; } }
async function retryIntent() { if (!pendingIntent.value || recovering.value) return; const req = scope('retry'); recovering.value = true; try { const data = await api.post('/video/quote', pendingIntent.value.payload, { signal: req.signal }); if (!req.current()) return; quote.value = data; quotePayload.value = pendingIntent.value.payload; confirmDialog.value.showModal(); } catch (e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) recovering.value = false; } }
async function refreshDetail(id, revision) { const req = scope('detail'); try { const row = await api.get('/video/tasks/' + encodeURIComponent(id), { signal: req.signal }); if (!req.current() || detailRevision !== revision) return; detail.value = row; if (row.status === 'SUCCESS') { const value = await loadMedia(id, true); if (req.current() && detailRevision === revision) detailMedia.value = value; } } catch (e) { if (req.current() && detailRevision === revision) detailError.value = e.message; } }
async function openDetail(task) { resumeAt = 0; opener = document.activeElement; detailLoading.value = true; detailError.value = ''; detail.value = null; detailMedia.value = null; playError.value = ''; publishConfirm.value = deleteConfirm.value = false; detailDialog.value.showModal(); const revision = ++detailRevision; await refreshDetail(task.id, revision); if (current() && revision === detailRevision) detailLoading.value = false; }
function stopPlayer() { const element = player.value; if (element) { element.pause(); element.removeAttribute('src'); element.load(); } }
function closeDetail() { resumeAt = 0; ++detailRevision; controllers.get('detail')?.abort(); stopPlayer(); detailDialog.value?.close(); detail.value = null; detailMedia.value = null; opener?.focus?.({ preventScroll: true }); }
async function refreshPlayback() { if (!detail.value) return; const id = detail.value.id, revision = detailRevision; resumeAt = player.value?.currentTime || 0; playError.value = ''; const value = await loadMedia(id, true); if (current() && revision === detailRevision) { detailMedia.value = value; if (!value) playError.value = '暂时无法打开成片，请稍后重试。'; } }
function resumePlayer() { if (player.value && resumeAt > 0 && Number.isFinite(player.value.duration)) player.value.currentTime = Math.min(resumeAt, Math.max(0, player.value.duration - .1)); resumeAt = 0; }
function reuse(task) { form.prompt = task.prompt || ''; form.presetId = presets.value.some(p => p.id === task.presetId) ? task.presetId : form.presetId; form.mode = 'text'; form.ratio = task.ratio || '16:9'; form.seconds = task.params?.seconds ?? task.seconds ?? selected.value?.features.seconds?.[0] ?? 0; form.resolution = task.resolution || '720p'; form.seed = task.seed ?? ''; for (const key of ['style','motion','guidanceScale','frameRate','pan','tilt','rotate','zoom','negativePrompt','sound']) if (task.params?.[key] !== undefined) form[key] = task.params[key]; sourceTask.value = null; clearReferences(); materials.value=[]; if(videoToolMode(task.mode)){form.mode=task.mode;materials.value=task.mine?(task.materials||[]):[];for(const key of ['upscaleFactor','enhanceModel','syncMode','compression','noise','halo','grain','recoverDetail'])if(task.params?.[key]!==undefined)form[key]=task.params[key];form.customEnhance=['compression','noise','halo','grain','recoverDetail'].some(k=>task.params?.[k]!==undefined);} if (task.mine && task.mode==='image' && task.imageIds?.length) { form.mode = 'image'; references.value = task.imageIds.map(id => ({ id })); for (const id of task.imageIds) void assets.load({ url: '/api/upload/' + id + '/raw' }); } closeDetail(); nextTick(() => { if (current()) document.querySelector('#qv-prompt')?.focus(); }); }
async function beginTool(task,mode){const preset=presets.value.find(p=>p.ready&&p.features.modes.includes(mode));if(!preset)return ElMessage.warning('先在视频控制台准备支持这项处理的连接');const request=scope('tool-source');materialBusy.value=true;try{const item=await api.post('/video/materials/from-task/'+encodeURIComponent(task.id),{}, {signal:request.signal});if(!request.current())return;form.presetId=preset.id;form.mode=mode;form.prompt='';materials.value=[{...item,kind:'video'}];closeDetail();nextTick(()=>{if(current())document.querySelector('#qv-prompt')?.focus();});}catch(e){if(request.current())ElMessage.error(e.message);}finally{if(request.current())materialBusy.value=false;}}
function extend(task) { if (!task.mine || !task.canExtend) return; reuse(task); form.mode = 'extend'; sourceTask.value = task; form.prompt = selected.value?.profile === 'PIKA_1' ? task.prompt : ''; }
async function stopTask(task) { if (busy.has(task.id)) return; busy.add(task.id); try { const value = await api.post('/video/tasks/' + task.id + '/cancel'); if (!current()) return; if (detail.value?.id === task.id) detail.value = value; await loadTasks(); ElMessage.success(value.status === 'SUCCESS' ? '这一幕已完成，成片与结算结果已保留。' : '已停止等待，未结算的预留已处理。'); } catch (e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function togglePublish() { const task = detail.value; if (!task || busy.has(task.id)) return; busy.add(task.id); try { const value = await api.patch('/video/tasks/' + task.id + '/publish', { published: !task.published }); if (!current()) return; if (detail.value?.id === task.id) detail.value = value; publishConfirm.value = false; await loadTasks(); } catch (e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function removeTask() { const task = detail.value; if (!task || busy.has(task.id)) return; busy.add(task.id); try { await api.del('/video/tasks/' + task.id); if (!current()) return; closeDetail(); await loadTasks(); } catch (e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function restoreTask(task) { if (busy.has(task.id)) return; busy.add(task.id); try { await api.post('/video/tasks/' + task.id + '/restore'); if (!current()) return; await loadTasks(); ElMessage.success('已恢复到我的片库，仅自己可见。'); } catch (e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function downloadMovie() { if (!detail.value || downloading.value) return; downloading.value = true; const id = detail.value.id, revision = detailRevision; try { const value = await loadMedia(id, true); if (!value || !current() || revision !== detailRevision) return; const link = document.createElement('a'); link.href = value.downloadUrl; link.download = 'QGauss-film-' + id.slice(-10) + '.mp4'; document.body.append(link); link.click(); link.remove(); } finally { if (current()) downloading.value = false; } }
function normalize() { const p = selected.value; if (!p) return; if (!p.features.modes.includes(form.mode)) form.mode = p.features.modes[0] || 'text'; if (!allowedRatios.value.includes(form.ratio)) form.ratio = allowedRatios.value[0]; if (!timeChoices.value.includes(form.seconds)) form.seconds = timeChoices.value[0]; if (!p.features.resolutions.includes(form.resolution)) form.resolution = p.features.resolutions[0] || ''; }
watch([selected, () => form.mode], normalize); watch(tab, () => { page.value = 1; void loadTasks(); });
function dispose() { if (!alive) return; alive = false; clearInterval(timer); for (const controller of controllers.values()) controller.abort(); stopPlayer(); detailDialog.value?.close(); confirmDialog.value?.close(); for (const url of localUrls.values()) URL.revokeObjectURL(url); localUrls.clear(); assets.close(); media.clear(); }
watch(() => auth.user?.id, value => { if (value !== owner) { intentStore.clear(); dispose(); } });
onMounted(async () => { await Promise.all([loadOptions(), loadTasks()]); if (current()) { if (pendingIntent.value) void recoverIntent(); timer = setInterval(() => { if (current() && !loading.value && (activeCount.value || detail.value && videoActive(detail.value.status))) void loadTasks(); }, 3500); } });
onUnmounted(dispose);
</script>
